import {SHEET_DICE,SHEET_SKILLS,SHEET_APTITUDES,ITEM_TYPES,STARTER_ITEMS,emptySheet,updateSheet} from '../sheet-model.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={fisico:'Físico',mente:'Mente',emocao:'Emoção',executor:'Executor',analista:'Analista',vigilante:'Vigilante',agente:'Agente',sobrevivente:'Sobrevivente',equipamento:'Equipamento',ferramenta:'Ferramenta',consumivel:'Consumível',tecnologia:'Tecnologia',documento:'Documento',especial:'Especial',outro:'Outro'};
const portraits=[['iris','Íris','iris.jpg'],['andre','André','andre.jpg'],['matias','Matias','matias.jpg'],['celine','Celine','celine.png'],['leia','Léia','leia.jpg'],['samuel','Samuel','samuel.jpg']];
const select=(name,value,options)=>`<select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,labels[o]||o];return `<option value="${v}" ${v===value?'selected':''}>${l}</option>`;}).join('')}</select>`;
const input=(label,name,value,type='text',extra='')=>`<label><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value)=>`<label><span>${label}</span><textarea name="${name}" rows="4">${esc(value)}</textarea></label>`;
const portraitURL=value=>typeof value==='string'&&/^(https?:\/\/|data:image\/(png|jpeg|webp|gif);base64,)/i.test(value)?value:'';
export function prepareSheet(source){const d=emptySheet(),s=source&&typeof source==='object'?source:{};return {...d,...s,attributes:{...d.attributes,...s.attributes},resources:{...d.resources,...s.resources},skills:{...d.skills,...s.skills},aptidoes:{...d.aptidoes,...s.aptidoes},inventory:Array.isArray(s.inventory)?s.inventory:[],abilities:Array.isArray(s.abilities)?s.abilities:[]};}
export function sheetMarkup(source,identity){
 const s=prepareSheet(source),r=s.resources,portrait=portraitURL(s.portrait),initials=(s.name||identity.name||'CR').trim().split(/\s+/).map(w=>w[0]).slice(0,2).join('');
 return `<form class="sheet-quick-form" novalidate><section class="agent-dossier"><div class="agent-photo">${portrait?`<img src="${esc(portrait)}" alt="Retrato do personagem">`:`<span aria-hidden="true">${esc(initials)}</span>`}<label class="agent-photo-upload">Trocar foto<input type="file" accept="image/png,image/jpeg,image/webp" data-photo aria-label="Enviar foto do agente"></label></div><div class="agent-dossier-name"><span>C.R.I.S. // REGISTRO PESSOAL</span><h3>${esc(s.name||'Novo personagem')}</h3><p>${esc(labels[s.profile]||s.profile)} · ${esc(s.occupation||'Ocupação não informada')}</p><div class="agent-tags"><b>NÍVEL ${esc(s.level)}</b><b>NEX ${esc(s.nex)}%</b></div><details class="agent-photo-options"><summary>Retratos do CRIS</summary><div>${portraits.map(([key,name])=>`<button type="button" data-portrait="${key}">${name}</button>`).join('')}<button type="button" data-clear-photo>Sem foto</button></div></details></div><input type="hidden" name="portrait" value="${esc(s.portrait)}"></section><nav class="sheet-tabs" role="tablist" aria-label="Seções da ficha">${[['record','Ficha'],['inventory','Inventário'],['abilities','Habilidades'],['story','História']].map(([key,name],i)=>`<button type="button" role="tab" id="sheetTab-${key}" data-tab="${key}" aria-controls="sheetPanel-${key}" aria-selected="${i===0}">${name}</button>`).join('')}</nav><section role="tabpanel" id="sheetPanel-record" aria-labelledby="sheetTab-record" data-panel="record"><div class="sheet-resource-grid">${[['pv','Vida','PV'],['pd','Determinação','PD']].map(([k,title,short])=>`<article class="agent-resource ${k}"><div><strong>${title}</strong><span>${short}</span></div><div class="agent-resource-values"><button type="button" data-resource="${k}Current" data-delta="-1" aria-label="Diminuir ${title}">−</button>${input(title+' atual',k+'Current',r[k+'Current'],'number','min="0" max="9999" required')}<span>/</span>${input(title+' máxima',k+'Max',r[k+'Max'],'number','min="0" max="9999" required')}<button type="button" data-resource="${k}Current" data-delta="1" aria-label="Aumentar ${title}">+</button></div></article>`).join('')}</div><div class="agent-attributes">${['fisico','mente','emocao'].map(k=>`<label><span>${labels[k]}</span>${select('attribute.'+k,s.attributes[k],SHEET_DICE)}</label>`).join('')}</div><details class="agent-identity-fields" ${s.name?'':'open'}><summary>Identidade e evolução</summary><div class="sheet-edit-grid">${input('Nome do personagem','name',s.name,'text','required maxlength="120"')}${input('Jogador','player',s.player||identity.name)}<label><span>Tipo</span>${select('type',s.type,['agente','sobrevivente'])}</label><label><span>Perfil</span>${select('profile',s.profile,['executor','analista','vigilante'])}</label>${input('Ocupação','occupation',s.occupation)}${input('Nível','level',s.level,'number','min="1" max="10" required')}${input('NEX (%)','nex',s.nex,'number','min="0" max="100" required')}</div><p class="sheet-empty">Evolução combinada com o mestre. O nível não aplica bônus automaticamente.</p></details><div class="agent-skills-head"><h4>Perícias e aptidões</h4><input type="search" placeholder="Buscar perícia…" aria-label="Buscar perícia" data-skill-search></div><div class="sheet-skills">${SHEET_SKILLS.map(([k,l,a])=>`<label data-skill="${l.toLocaleLowerCase('pt-BR')}"><span>${l}<small> + ${labels[s.skills[k]?.atributo||a]}</small></span>${select('skill.'+k,s.skills[k]?.die||'d4',SHEET_DICE)}</label>`).join('')}${SHEET_APTITUDES.map(([k,l])=>`<label data-skill="${l.toLocaleLowerCase('pt-BR')}"><span>${l}<small>aptidão + Mente</small></span>${select('aptitude.'+k,s.aptidoes[k]?.die||'d4',SHEET_DICE)}</label>`).join('')}</div></section><section role="tabpanel" id="sheetPanel-inventory" aria-labelledby="sheetTab-inventory" data-panel="inventory" hidden><div class="sheet-section-heading"><h4>Inventário <small>${s.inventory.length} itens</small></h4><button type="button" data-add="inventory">+ Criar item</button></div><div class="sheet-catalog"><label><span>Equipamentos iniciais</span>${select('catalog','',[['','Escolher item…'],...STARTER_ITEMS.map((i,n)=>[String(n),i.name])])}</label><button type="button" data-catalog>Adicionar</button></div><div data-list="inventory">${s.inventory.length?s.inventory.map((i,n)=>`<article class="agent-inventory-item" data-row="${n}" data-group="inventory"><div class="sheet-edit-grid">${input('Nome do item','inventory.'+n+'.name',i.name)}<label><span>Tipo de item</span>${select('inventory.'+n+'.type',i.type||'equipamento',ITEM_TYPES)}</label>${input('Quantidade','inventory.'+n+'.quantity',i.quantity??1,'number','min="1" max="9999" required')}<label class="sheet-check"><input type="checkbox" name="inventory.${n}.equipped" ${i.equipped?'checked':''}>Equipado</label></div>${area('Descrição e propriedades','inventory.'+n+'.details',i.details)}<button type="button" class="sheet-remove" data-remove="${n}" data-group="inventory">Remover item</button></article>`).join(''):'<p class="agent-empty">Nenhum item registrado. Adicione um equipamento ou crie algo encontrado na campanha.</p>'}</div></section><section role="tabpanel" id="sheetPanel-abilities" aria-labelledby="sheetTab-abilities" data-panel="abilities" hidden><div class="sheet-section-heading"><h4>Habilidades</h4><button type="button" data-add="abilities">+ Habilidade</button></div><div data-list="abilities">${s.abilities.length?s.abilities.map((a,n)=>`<article class="agent-inventory-item" data-row="${n}" data-group="abilities"><div class="sheet-edit-grid">${input('Nome da habilidade','abilities.'+n+'.name',a.name)}${input('Origem','abilities.'+n+'.origin',a.origin)}${input('Custo','abilities.'+n+'.cost',a.cost)}</div>${area('Descrição da habilidade','abilities.'+n+'.description',a.description)}<button type="button" class="sheet-remove" data-remove="${n}" data-group="abilities">Remover habilidade</button></article>`).join(''):'<p class="agent-empty">Registre aqui as habilidades do seu personagem.</p>'}</div></section><section role="tabpanel" id="sheetPanel-story" aria-labelledby="sheetTab-story" data-panel="story" hidden><div class="agent-story">${area('Conceito','concept',s.concept)+area('Aparência','appearance',s.appearance)+area('História','history',s.history)+area('Anotações pessoais','notes',s.notes)}</div></section><div class="sheet-save-bar"><p class="sheet-save-status" role="status">Ficha carregada da sua conta.</p><button type="submit" class="sheet-save">Salvar ficha</button></div></form>`;
}
export async function openBoardSheet({bridge,identity}){
 const existing=document.getElementById('crisSheetDrawer');if(existing){existing.querySelector('header button').focus();return;}
 const previous=document.activeElement,drawer=document.createElement('aside');drawer.id='crisSheetDrawer';drawer.className='cris-sheet-drawer agent-sheet-v2';drawer.setAttribute('role','dialog');drawer.setAttribute('aria-label','Minha ficha');
 drawer.innerHTML='<header><div><small>C.R.I.S. // DOSSIÊ PESSOAL</small><h2>Ficha de agente</h2></div><button type="button" aria-label="Fechar ficha">×</button></header><div class="sheet-drawer-body"><p>Carregando sua ficha…</p></div>';
 let dirty=false,saving=false,activeTab='record',sheet;
 const body=drawer.querySelector('.sheet-drawer-body'),unload=e=>{if(dirty){e.preventDefault();e.returnValue='';}};
 const close=()=>{if(saving||dirty&&!confirm('Descartar alterações não salvas da ficha?'))return;window.removeEventListener('beforeunload',unload);drawer.remove();previous?.focus();};
 drawer.querySelector('header button').onclick=close;drawer.onkeydown=e=>{e.stopPropagation();if(e.key==='Escape')close();};for(const event of ['pointerdown','pointerup','click','wheel'])drawer.addEventListener(event,e=>e.stopPropagation());
 document.body.append(drawer);window.addEventListener('beforeunload',unload);drawer.querySelector('header button').focus();
 try{sheet=prepareSheet(await bridge.loadSheet());if(!drawer.isConnected){window.removeEventListener('beforeunload',unload);return;}}
 catch(error){body.textContent='Não foi possível abrir sua ficha: '+error.message;return;}
 const collect=()=>Object.fromEntries(new FormData(body.querySelector('form')));
 function setTab(key,focus=false){activeTab=key;for(const b of body.querySelectorAll('[data-tab]')){const selected=b.dataset.tab===key;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;if(selected&&focus)b.focus();}for(const p of body.querySelectorAll('[data-panel]'))p.hidden=p.dataset.panel!==key;}
 function showError(error){body.querySelector('[role=status]').textContent=error.message||String(error);}
 function render(){
  const scroll=body.scrollTop;body.innerHTML=sheetMarkup(sheet,identity);setTab(activeTab);body.scrollTop=scroll;
  const form=body.querySelector('form'),status=form.querySelector('[role=status]');
  const changed=()=>{dirty=true;status.textContent='Alterações não salvas.';};form.oninput=changed;form.onchange=changed;
  const mutate=fn=>{try{sheet=updateSheet(sheet,collect(),{validate:false});fn();dirty=true;render();body.querySelector('[role=status]').textContent='Alterações não salvas.';}catch(error){showError(error);}};
  for(const b of form.querySelectorAll('[data-tab]')){b.onclick=()=>{setTab(b.dataset.tab);body.scrollTop=0;};b.onkeydown=e=>{const tabs=[...form.querySelectorAll('[data-tab]')],i=tabs.indexOf(b);if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setTab(tabs[next].dataset.tab,true);body.scrollTop=0;}};}
  for(const b of form.querySelectorAll('[data-add]'))b.onclick=()=>mutate(()=>sheet[b.dataset.add].push(b.dataset.add==='inventory'?{name:'',type:'equipamento',quantity:1,equipped:false,details:''}:{name:'',origin:'',cost:'',description:''}));
  for(const b of form.querySelectorAll('[data-remove]'))b.onclick=()=>mutate(()=>sheet[b.dataset.group].splice(Number(b.dataset.remove),1));
  form.querySelector('[data-catalog]').onclick=()=>{const index=form.elements.namedItem('catalog').value;if(index!=='')mutate(()=>sheet.inventory.push(structuredClone(STARTER_ITEMS[Number(index)])));};
  for(const b of form.querySelectorAll('[data-resource]'))b.onclick=()=>{const input=form.elements.namedItem(b.dataset.resource),n=Number(input.value)||0;input.value=String(Math.max(0,Math.min(9999,n+Number(b.dataset.delta))));changed();};
  form.querySelector('[data-skill-search]').oninput=e=>{e.stopPropagation();const query=e.target.value.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/\p{Diacritic}/gu,'');for(const row of form.querySelectorAll('[data-skill]'))row.hidden=!row.dataset.skill.normalize('NFD').replace(/\p{Diacritic}/gu,'').includes(query);};
  for(const b of form.querySelectorAll('[data-portrait]'))b.onclick=()=>mutate(()=>{const found=portraits.find(p=>p[0]===b.dataset.portrait);sheet.portrait=new URL('../assets/'+found[2],import.meta.url).href;});
  form.querySelector('[data-clear-photo]').onclick=()=>mutate(()=>sheet.portrait='');
  form.querySelector('[data-photo]').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('Use uma imagem PNG, JPG ou WebP de até 8 MB.');const url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();const canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(img.naturalWidth,img.naturalHeight));canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const portrait=canvas.toDataURL('image/webp',0.88);if(drawer.isConnected)mutate(()=>sheet.portrait=portrait);}finally{URL.revokeObjectURL(url);}}catch(error){showError(error);}};
  form.onsubmit=async e=>{
   e.preventDefault();if(saving)return;
   const invalid=[...form.elements].find(input=>input.willValidate&&!input.checkValidity());if(invalid){const panel=invalid.closest('[data-panel]');if(panel)setTab(panel.dataset.panel);const details=invalid.closest('details');if(details)details.open=true;invalid.focus();invalid.reportValidity();status.textContent='Confira o campo indicado antes de salvar.';return;}
   const button=form.querySelector('[type=submit]');saving=true;button.disabled=true;form.inert=true;status.textContent='Salvando na sua conta…';
   try{if(bridge.identity?.userId&&bridge.identity.userId!==identity.userId)throw Error('A conta mudou. Reabra a ficha.');const next=updateSheet(sheet,collect());await bridge.saveSheet(next);sheet=next;dirty=false;render();body.querySelector('[role=status]').textContent='Ficha salva na sua conta.';}catch(error){showError(Error((error.message||'Falha ao salvar')+' Suas alterações foram mantidas nesta tela.'));}finally{saving=false;button.disabled=false;form.inert=false;}
  };
 }
 render();
}
